using AcxiomCRM.Models;using AcxiomCRM.Data;using AcxiomCRM.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using System.Text;
namespace AcxiomCRM.Controllers;
public record ReportRow(string Name,string Status,string Owner,DateTime Date,decimal Value);
public class ReportsController(CrmDb db,CrmService crm):Controller{
public async Task<IActionResult> Index(string type="customers",string? q = null, string? status = null, string? owner = null, DateTime? from = null, DateTime? to = null, bool export = false){List<ReportRow> rows;switch(type){
case "customers": rows=await crm.Scope<Customer>().Select(x=>new ReportRow(x.CustomerName,x.Status,x.AssignedTo,x.CreatedDate,0)).ToListAsync();break;
case "leads":case "conversion":rows=await crm.Scope<Lead>().Select(x=>new ReportRow(x.LeadName,x.Status,x.AssignedTo,x.CreatedDate,x.ExpectedValue)).ToListAsync();break;
case "followups":rows=await crm.Scope<FollowUp>().Select(x=>new ReportRow(x.Subject,x.Status,x.AssignedTo,x.FollowUpDate,0)).ToListAsync();break;
case "opportunities":case "pipeline":rows=await crm.Scope<Opportunity>().Where(x=>type!="pipeline"||x.Status=="Open").Select(x=>new ReportRow(x.OpportunityName,x.Stage,x.AssignedTo,x.CreatedDate,type=="pipeline"?x.Amount*x.Probability/100:x.Amount)).ToListAsync();break;
case "activities":if(User.IsInRole("SalesExecutive"))return Forbid();rows=await crm.Scope<Activity>().Select(x=>new ReportRow(x.Subject,x.Status,x.AssignedTo,x.ActivityDate,0)).ToListAsync();break;
case "audit":if(!User.IsInRole("Admin"))return Forbid();rows=await db.AuditLogs.Select(x=>new ReportRow(x.EntityName,x.Action,x.UserId??"",x.CreatedDate,0)).ToListAsync();break;default:return NotFound();}
rows=rows.Where(x=>(q==null||x.Name.Contains(q,StringComparison.OrdinalIgnoreCase))&&(status==null||x.Status==status)&&(owner==null||x.Owner==owner)&&(!from.HasValue||x.Date.Date>=from.Value.Date)&&(!to.HasValue||x.Date.Date<=to.Value.Date)).OrderByDescending(x=>x.Date).ToList();if(export){string Cell(string s){if(s.Length>0&&"=+-@\t\r\n".Contains(s[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}var csv="Name,Status,Owner,Date,Value\n"+string.Join("\n",rows.Select(x=>string.Join(",",Cell(x.Name),Cell(x.Status),Cell(x.Owner),x.Date.ToString("yyyy-MM-dd"),x.Value.ToString(System.Globalization.CultureInfo.InvariantCulture))));return File(Encoding.UTF8.GetBytes(csv),"text/csv",type+".csv");}ViewBag.Type=type;ViewBag.Q=q;ViewBag.Status=status;ViewBag.Owner=owner;ViewBag.From=from?.ToString("yyyy-MM-dd");ViewBag.To=to?.ToString("yyyy-MM-dd");return View(rows);}
[HttpGet("/api/reports/pipeline")]public async Task<IActionResult> Pipeline()=>Json(await crm.Scope<Opportunity>().Where(x=>x.Status=="Open").GroupBy(x=>x.Stage).Select(g=>new{stage=g.Key,amount=g.Sum(x=>x.Amount),weighted=g.Sum(x=>x.Amount*x.Probability/100)}).ToListAsync());}
